import sys,subprocess,json,hashlib
from pathlib import Path
r=Path('.agent-runs/performance-v2');python=r/'automl-env/Scripts/python.exe'
for seed in range(2401,2404):
 configs=[(model,profile) for model in ['svm','lightgbm'] for profile in ['full','quarter','eighth']]+[('lightgbm','native')]
 if seed%2==0:configs.reverse()
 for model,profile in configs:
  label=f'drybean-native-{model}-{profile}-{seed}';print('START',label,flush=True)
  with (r/(label+'.log')).open('w',encoding='utf-8') as out:result=subprocess.run([str(python),str(r/'drybean_native_worker.py'),str(seed),model,profile],stdout=out,stderr=subprocess.STDOUT,timeout=900)
  print('EXIT',label,result.returncode,flush=True)
  if result.returncode:sys.exit(result.returncode)
for name,sha in json.loads((r/'drybean-native-source-sha256.json').read_text(encoding='utf-8')).items():assert hashlib.sha256((r/'drybean-native-source'/name).read_bytes()).hexdigest()==sha
print('Completed42fits; source hashes unchanged',flush=True)
